package com.renthouse.operation.service;
import com.renthouse.auth.service.CurrentUser;import com.renthouse.auth.enums.UserRole;import com.renthouse.common.api.PageResponse;import com.renthouse.common.exception.BusinessException;import com.renthouse.common.id.SnowflakeIdGenerator;import com.renthouse.operation.controller.AgentListingController.Create;import com.renthouse.operation.controller.AgentListingController.Item;import com.renthouse.operation.controller.AgentListingController.Media;import com.renthouse.operation.controller.AgentListingController.Special;import com.renthouse.operation.mapper.AgentListingMapper;import com.renthouse.operation.service.AgentListingService;import java.time.LocalDateTime;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AgentListingServiceImpl implements AgentListingService { private final AgentListingMapper mapper; private final SnowflakeIdGenerator ids; public AgentListingServiceImpl(AgentListingMapper mapper,SnowflakeIdGenerator ids){this.mapper=mapper;this.ids=ids;} private long agent(){CurrentUser.requireRole(UserRole.AGENT);return CurrentUser.require().id();} @Override @Transactional public Item create(Create r){long a=agent();if(mapper.countUnit(r.unitId(),a)==0)throw new BusinessException("UNIT_NOT_FOUND","房屋不存在或无权操作",HttpStatus.NOT_FOUND);long id=ids.nextId();LocalDateTime n=LocalDateTime.now();mapper.insertListing(id,r.unitId(),a,r.title(),r.communityName(),r.district(),r.address(),r.rentCent(),r.depositCent(),n);return new Item(String.valueOf(id),r.title(),r.rentCent(),"DRAFT",false,"VACANT");} @Override public PageResponse<Item> list(int page,int size){long a=agent();page=Math.max(1,page);size=Math.min(50,Math.max(1,size));int offset=(page-1)*size;return PageResponse.of(mapper.listListings(a,offset,size),mapper.countListings(a),page,size);}@Override @Transactional public void publish(long id){if(mapper.publishListing(id,agent(),LocalDateTime.now())==0)throw new BusinessException("LISTING_NOT_PUBLISHABLE","房源不可发布",HttpStatus.CONFLICT);}@Override @Transactional public void offline(long id){if(mapper.offlineListing(id,agent(),LocalDateTime.now())==0)throw new BusinessException("LISTING_NOT_FOUND","房源不存在或无权操作",HttpStatus.NOT_FOUND);}@Override @Transactional public void updateSpecial(long id,Special r){if(mapper.updateSpecial(id,agent(),r.enabled(),r.sort(),LocalDateTime.now())==0)throw new BusinessException("LISTING_NOT_FOUND","房源不存在或无权操作",HttpStatus.NOT_FOUND);}@Override @Transactional public void addMedia(long id,Media r){if(mapper.countListing(id,agent())==0)throw new BusinessException("LISTING_NOT_FOUND","房源不存在或无权操作",HttpStatus.NOT_FOUND);mapper.insertMedia(ids.nextId(),id,r.type(),r.url(),r.coverUrl(),r.sort(),LocalDateTime.now());}}
